def f(x):
    """f: R^2 -> R^3"""
    return jnp.array([x[0]**2 + x[1], x[0] * x[1], jnp.sin(x[0])])

a = jnp.array([1.0, 2.0])
print("f(a) =", f(a))

def g(y):
    """g: R^3 -> R^2"""
    return jnp.array([y[0] * y[2] + y[1]**2, jnp.exp(y[0]) - y[2]])

def h(x):
    """h = g o f: R^2 -> R^2"""
    return g(f(x))

print("f(a) =", f(a))
print("h(a) = g(f(a)) =", h(a))
